import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BiXHgXAn.js";const g=JSON.parse('{"title":"Releasing","description":"Task release process including GoReleaser, Homebrew, npm, Snapcraft, winget, and other package managers","frontmatter":{"title":"Releasing","description":"Task release process including GoReleaser, Homebrew, npm, Snapcraft, winget, and other package managers","section":"Contributing","docType":"contributing","outline":"deep"},"headers":[],"relativePath":"docs/releasing.md","filePath":"next/docs/releasing.md"}'),o={name:"docs/releasing.md"};function n(r,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="releasing" tabindex="-1">Releasing <a class="header-anchor" href="#releasing" aria-label="Permalink to &quot;Releasing&quot;">​</a></h1><p>The release process of Task is done with the help of <a href="https://goreleaser.com/" target="_blank" rel="noreferrer">GoReleaser</a>. You can test the release process locally by calling the <code>goreleaser:test</code> task of the Taskfile.</p><p><a href="https://github.com/go-task/task/actions" target="_blank" rel="noreferrer">GitHub Actions</a> should release artifacts automatically when a new Git tag is pushed to <code>main</code> branch (raw executables and DEB and RPM packages).</p><p>The body of the GitHub release is the section of the <code>CHANGELOG.md</code> matching the version being released, extracted by <code>go run ./cmd/release --notes</code>. A version without changelog entries is released with an empty body.</p><p>Raw executables can also be reproduced and verified locally by checking out a specific tag and calling <code>goreleaser build</code>, using the Go version defined in the above GitHub Actions.</p><h2 id="website" tabindex="-1">Website <a class="header-anchor" href="#website" aria-label="Permalink to &quot;Website&quot;">​</a></h2><p><code>task release:&lt;version&gt;</code> promotes the documentation before tagging: the docs in <code>website/src/next/docs</code>, their sidebar and the <code>next-*</code> JSON schemas are copied over their published counterparts, so the released tag carries the docs of the version it ships. The release workflow then runs <code>task website:deploy:prod</code>.</p><p>A new blog post is a Markdown file in <code>website/src/next/blog</code> with no file at the same relative path in <code>website/src/latest/blog</code>, excluding <code>index.md</code>. Renaming a post therefore makes it new. On the <code>next</code> site, new posts display the build date in UTC (<code>YYYY-MM-DD</code>) and are sorted using that date, without changing the source files. The <code>latest</code> site uses only the stored dates.</p><p>During release preparation, <code>cmd/release</code> replaces or adds the <code>date</code> in each new post&#39;s frontmatter with the same local date used for the changelog. It validates all new posts&#39; frontmatter before writing; an error identifies the file to fix. It then copies the blog to <code>latest</code>, so both copies carry the same date in the release commit. This is the preparation date, even if publication on GitHub happens later. Already published posts keep their dates, including when their content changes. The <code>--version</code> and <code>--notes</code> flags do not write files.</p><p>Because taskfile.dev is built from the latest copy, it can be redeployed at any time between releases - to publish a blog post or a documentation fix - without exposing the docs of unreleased features:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> website:deploy:prod</span></span></code></pre></div><h2 id="package-managers" tabindex="-1">Package managers <a class="header-anchor" href="#package-managers" aria-label="Permalink to &quot;Package managers&quot;">​</a></h2><p>GoReleaser will automatically publish the release to most package managers:</p><ul><li>Cloudsmith (DEB and RPM repositories)</li><li>Homebrew</li><li>npm</li><li>Snapcraft</li><li>winget</li></ul><p>Once the release is published, GoReleaser announces it on the <a href="https://discord.gg/6TY36E39UK" target="_blank" rel="noreferrer">Discord server</a>. Nightly releases are not announced.</p><p>These package managers are updated automatically by the community:</p><ul><li><a href="https://github.com/ScoopInstaller/Main/blob/master/bucket/task.json" target="_blank" rel="noreferrer">Scoop</a></li><li><a href="https://github.com/NixOS/nixpkgs/blob/master/pkgs/by-name/go/go-task/package.nix" target="_blank" rel="noreferrer">Nix</a></li></ul>`,17)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
